import type { AgentId } from "./agents";

/**
 * Reconstruction blueprint — what the swarm builds, in what order.
 *
 * The blueprint is generated by walking the live portfolio DOM in hierarchy
 * order and classifying every visible element as a build unit. Nothing is
 * measured into coordinates here: rects are read from the live layout on
 * every frame, so the plan stays correct across reflows, breakpoints and
 * dynamic content.
 *
 * The original page is never cloned or replaced. Each unit is hidden in
 * place with a `clip-path` — layout untouched, still in the accessibility
 * tree, no longer hit-testable — and opened again by writing `--rb-p` as the
 * swarm works on it. Removing the attributes restores the real element.
 */

export type UnitKind = "text" | "media" | "action" | "block";
export type UnitAction = "type" | "arrange" | "click" | "resize";
export type UnitState = "pending" | "building" | "built";

/** Units may be HTML or inline SVG — icons are rebuilt too. */
export type UnitEl = HTMLElement | SVGElement;

export interface BuildUnit {
  /** Stable within a scan; keys React rows and box entries. */
  id: number;
  el: UnitEl;
  kind: UnitKind;
  /** Which construction frame the stage draws around it. */
  action: UnitAction;
  agent: AgentId;
  /** Shown on that agent's chip while the unit is being built. */
  label: string;
  /** How long the reveal runs once the cursor is in place (ms). */
  duration: number;
  /** Nearest ancestor unit — a unit may not start before its container. */
  parent: BuildUnit | null;
  state: UnitState;
  /** Active-clock ms when a cursor claimed it. */
  t0: number;
  /** Active-clock ms when the cursor arrived and the reveal began. */
  armAt: number | null;
  /** Reveal progress 0..1, written to `--rb-p`. */
  p: number;
  claimedBy: AgentId | null;
}

export interface Blueprint {
  units: BuildUnit[];
  unitByEl: Map<UnitEl, BuildUnit>;
  builtCount: number;
  allBuilt(): boolean;
  claim(unit: BuildUnit, agent: AgentId, clock: number): void;
  progress(unit: BuildUnit, p: number): void;
  markBuilt(unit: BuildUnit): void;
  revealAll(): void;
  builtElements(): Set<UnitEl>;
  teardown(): void;
}

const INTERACTIVE_SELECTOR =
  "a,button,input,select,textarea,summary,label," +
  "[role='button'],[role='link'],[role='menuitem'],[role='tab'],[role='checkbox'],[role='switch']";
const MEDIA_SELECTOR = "img,picture,video,canvas,iframe,svg,object,embed";
/** Visually hidden text and inert subtrees are not part of the rebuild. */
const SKIP_SELECTOR = "script,style,template,noscript,.sr-only,[hidden]";

const HEADING_RE = /^H[1-6]$/;
const LABEL_MAX = 28;

const clamp = (v: number, min: number, max: number) => (v < min ? min : v > max ? max : v);

/** True when the element carries its own visible text (not just children). */
function hasDirectText(el: Element): boolean {
  for (const node of el.childNodes) {
    if (node.nodeType === Node.TEXT_NODE && (node.textContent ?? "").trim()) return true;
  }
  return false;
}

/** True when the element paints something of its own: fill, border or shadow. */
function hasOwnVisual(cs: CSSStyleDeclaration): boolean {
  const bg = cs.backgroundColor;
  if (bg && bg !== "transparent" && bg !== "rgba(0, 0, 0, 0)") return true;
  if (cs.backgroundImage && cs.backgroundImage !== "none") return true;
  if (
    parseFloat(cs.borderTopWidth) > 0 ||
    parseFloat(cs.borderRightWidth) > 0 ||
    parseFloat(cs.borderBottomWidth) > 0 ||
    parseFloat(cs.borderLeftWidth) > 0
  ) {
    return true;
  }
  if (cs.boxShadow && cs.boxShadow !== "none") return true;
  if (cs.textShadow && cs.textShadow !== "none") return true;
  return false;
}

/**
 * Decide how one element gets rebuilt: its frame, its agent, its chip label
 * and how long the reveal takes. `cs` is only supplied for containers, which
 * are the only units that need computed styles.
 */
function createUnit(
  el: UnitEl,
  parent: BuildUnit | null,
  id: number,
  cs: CSSStyleDeclaration | null,
  isRoot: boolean
): BuildUnit {
  const text = (el.textContent ?? "").trim();
  const unit: BuildUnit = {
    id,
    el,
    kind: "text",
    action: "type",
    agent: "writer",
    label: "Writing copy…",
    duration: 600,
    parent,
    state: "pending",
    t0: 0,
    armAt: null,
    p: 0,
    claimedBy: null,
  };

  // Media first: a link wrapping a picture still reads as a picture to place.
  if (el.matches(MEDIA_SELECTOR)) {
    unit.kind = "media";
    unit.action = "arrange";
    const tag = el.tagName.toLowerCase();
    if (tag === "svg") {
      unit.label = "Adding icon…";
      unit.duration = 380;
      unit.agent = id % 2 === 0 ? "designer" : "developer";
    } else if (tag === "img") {
      unit.label = "Placing image…";
      unit.duration = 720;
      unit.agent = "designer";
    } else {
      unit.label = "Adding media…";
      unit.duration = 640;
      unit.agent = "developer";
    }
    return unit;
  }

  if (el.matches(INTERACTIVE_SELECTOR)) {
    unit.kind = "action";
    unit.action = "click";
    unit.agent = "developer";
    const tag = el.tagName.toLowerCase();
    unit.label =
      tag === "button"
        ? "Wiring button…"
        : tag === "input" || tag === "textarea" || tag === "select"
          ? "Setting up field…"
          : "Adding link…";
    unit.duration = 520;
    return unit;
  }

  if (cs) {
    // Container: it paints its own box, so the swarm frames it first and
    // nothing inside may start until it has settled.
    unit.kind = "block";
    unit.action = "resize";
    const decorative = el.getAttribute("aria-hidden") === "true" && !text;
    if (isRoot) {
      unit.label = "Laying out section…";
      unit.agent = id % 2 === 0 ? "designer" : "developer";
      unit.duration = 620;
    } else if (decorative) {
      unit.label = "Adding accents…";
      unit.agent = "designer";
      unit.duration = 240;
    } else if (cs.display === "grid") {
      unit.label = "Arranging grid…";
      unit.agent = "editor";
      unit.duration = 560;
    } else {
      unit.label = "Building panel…";
      unit.agent = id % 2 === 0 ? "designer" : "developer";
      unit.duration = 460;
    }
    return unit;
  }

  // Plain text leaf: headings and long copy read as typing, short fragments
  // as labels, and every third paragraph goes to the editor for variety.
  unit.kind = "text";
  unit.action = "type";
  if (HEADING_RE.test(el.tagName)) {
    unit.agent = "writer";
    unit.label = "Typing heading…";
    unit.duration = clamp(300 + text.length * 7, 480, 1200);
  } else if (text.length <= LABEL_MAX) {
    unit.agent = "designer";
    unit.label = "Setting label…";
    unit.duration = 380;
  } else if (id % 3 === 2) {
    unit.agent = "editor";
    unit.label = "Reviewing copy…";
    unit.duration = clamp(260 + text.length * 6, 420, 1150);
  } else {
    unit.agent = "writer";
    unit.label = "Writing paragraph…";
    unit.duration = clamp(260 + text.length * 6, 420, 1150);
  }
  return unit;
}

/**
 * Walk the page and build a fresh blueprint.
 *
 * When `previous` is given, its attributes are removed first and any unit it
 * had already rebuilt stays rebuilt, so a resize re-plans the page without
 * replaying work the visitor has already watched.
 */
export function scanBlueprint(previous: Blueprint | null): Blueprint {
  const keepBuilt = previous ? previous.builtElements() : new Set<UnitEl>();
  previous?.teardown();

  const units: BuildUnit[] = [];
  const unitByEl = new Map<UnitEl, BuildUnit>();
  let nextId = 0;

  const push = (unit: BuildUnit) => {
    units.push(unit);
    unitByEl.set(unit.el, unit);
  };

  const walk = (el: HTMLElement, parent: BuildUnit | null, isRoot: boolean) => {
    if (el.matches(SKIP_SELECTOR)) return;
    // No box at all (display:none subtree) — nothing visible to rebuild.
    if (el.getClientRects().length === 0) return;

    if (el.matches(MEDIA_SELECTOR) || el.matches(INTERACTIVE_SELECTOR) || hasDirectText(el)) {
      push(createUnit(el, parent, nextId++, null, isRoot));
      return;
    }

    const cs = getComputedStyle(el);
    if (hasOwnVisual(cs)) {
      const unit = createUnit(el, parent, nextId++, cs, isRoot);
      push(unit);
      for (const child of Array.from(el.children)) {
        if (child instanceof SVGElement) {
          if (child.getClientRects().length > 0) push(createUnit(child, unit, nextId++, null, false));
        } else if (child instanceof HTMLElement) {
          walk(child, unit, false);
        }
      }
      return;
    }

    // Invisible wrapper: pass the ancestor unit straight through.
    for (const child of Array.from(el.children)) {
      if (child instanceof SVGElement) {
        if (child.getClientRects().length > 0) push(createUnit(child, parent, nextId++, null, false));
      } else if (child instanceof HTMLElement) {
        walk(child, parent, false);
      }
    }
  };

  const roots: HTMLElement[] = Array.from(
    document.querySelectorAll<HTMLElement>("main > section[id]")
  );
  const footer = document.querySelector<HTMLElement>("footer");
  if (footer) roots.push(footer);
  for (const root of roots) walk(root, null, true);

  let builtCount = 0;
  for (const unit of units) {
    unit.el.setAttribute("data-rb-kind", unit.kind);
    if (keepBuilt.has(unit.el)) {
      unit.state = "built";
      unit.p = 1;
      unit.el.setAttribute("data-rb", "built");
      builtCount++;
    } else {
      unit.el.setAttribute("data-rb", "hidden");
    }
    unit.el.style.removeProperty("--rb-p");
  }

  const blueprint: Blueprint = {
    units,
    unitByEl,
    get builtCount() {
      return builtCount;
    },
    allBuilt: () => builtCount >= units.length,
    claim(unit, agent, clock) {
      unit.state = "building";
      unit.t0 = clock;
      unit.armAt = null;
      unit.p = 0;
      unit.claimedBy = agent;
      unit.el.setAttribute("data-rb", "building");
    },
    progress(unit, p) {
      unit.p = p;
      unit.el.style.setProperty("--rb-p", p.toFixed(3));
    },
    markBuilt(unit) {
      if (unit.state === "built") return;
      unit.state = "built";
      unit.p = 1;
      unit.armAt = null;
      unit.claimedBy = null;
      unit.el.setAttribute("data-rb", "built");
      unit.el.style.removeProperty("--rb-p");
      builtCount++;
    },
    revealAll() {
      for (const unit of units) blueprint.markBuilt(unit);
    },
    builtElements() {
      const set = new Set<UnitEl>();
      for (const unit of units) if (unit.state === "built") set.add(unit.el);
      return set;
    },
    teardown() {
      for (const unit of units) {
        unit.el.removeAttribute("data-rb");
        unit.el.removeAttribute("data-rb-kind");
        unit.el.style.removeProperty("--rb-p");
      }
    },
  };

  return blueprint;
}
